using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Reflection;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using ScreenText;
class RuntimeRepairsSmoke {
 static string Home=AppDomain.CurrentDomain.BaseDirectory,Self=Assembly.GetExecutingAssembly().Location;static void Check(bool b,string m){if(!b)throw new Exception(m);}static void Until(Func<bool> condition){var s=Stopwatch.StartNew();while(!condition()){if(s.ElapsedMilliseconds>8000)throw new Exception("Timed out waiting for owned probe");Thread.Sleep(25);}}
 static Process Spawn(string mode,string dir){return Process.Start(new ProcessStartInfo(Self,mode+" "+Backend.Quote(dir)){UseShellExecute=false,CreateNoWindow=true});}static void Record(string dir,string name){File.WriteAllText(Path.Combine(dir,name+".pid"),Process.GetCurrentProcess().Id.ToString());}static bool Alive(int id){try{using(var p=Process.GetProcessById(id))return !p.HasExited;}catch{return false;}}static void Gone(string dir){Until(()=>Directory.GetFiles(dir,"*.pid").All(f=>!Alive(Int32.Parse(File.ReadAllText(f)))));}
 static int Probe(string mode,string dir){Directory.CreateDirectory(dir);if(mode=="--owner"){var task=Backend.Run(Self,"--tree "+Backend.Quote(dir),null,Home,CancellationToken.None,30);task.GetAwaiter().GetResult();return 0;}if(mode=="--orphan"){var session=TransientSession.Create(dir);File.WriteAllText(Path.Combine(session.DirectoryPath,"input.png"),"test");File.WriteAllText(Path.Combine(dir,"ready"),session.DirectoryPath);Thread.Sleep(30000);return 0;}Record(dir,mode.Substring(2));if(mode=="--tree"||mode=="--exits"){Spawn("--branch",dir).Dispose();Until(()=>File.Exists(Path.Combine(dir,"leaf.pid")));if(mode=="--exits"){Console.OutputEncoding=new System.Text.UTF8Encoding(false);Console.Write("ready Ελληνικά");return 0;}}else if(mode=="--branch")Spawn("--leaf",dir).Dispose();Thread.Sleep(30000);return 0;}
 static async Task Requests(){
  using(var unrelated=Spawn("--unrelated",Path.Combine(Home,"unrelated"))){try{
   foreach(string mode in new[]{"cancel","timeout","exit","blocked","timeoutblocked"}){string dir=Path.Combine(Home,mode);Directory.CreateDirectory(dir);using(var cancel=new CancellationTokenSource()){var task=Backend.Run(Self,(mode=="exit"?"--exits":"--tree")+" "+Backend.Quote(dir),(mode=="blocked"||mode=="timeoutblocked")?new string('x',2000000):null,Home,cancel.Token,mode.StartsWith("timeout")?1:15);Until(()=>File.Exists(Path.Combine(dir,"leaf.pid")));if(mode=="cancel"||mode=="blocked")cancel.Cancel();bool expected=false;try{var result=await task;expected=mode=="exit"&&result=="ready Ελληνικά";}catch(OperationCanceledException){expected=mode=="cancel"||mode=="blocked";}catch(CodexException e){expected=mode.StartsWith("timeout")&&e.Issue==CodexIssue.Timeout;}Check(expected,"Unexpected request outcome: "+mode);Gone(dir);}}
   string crash=Path.Combine(Home,"crash");using(var owner=Spawn("--owner",crash)){Until(()=>File.Exists(Path.Combine(crash,"leaf.pid")));owner.Kill();owner.WaitForExit();Gone(crash);}Check(!unrelated.HasExited,"Unrelated process was terminated");
  }finally{if(!unrelated.HasExited){unrelated.Kill();unrelated.WaitForExit();}}}
 }
 static void Storage(){string root=Path.Combine(Home,"sessions");Directory.CreateDirectory(root);string path;using(var session=TransientSession.Create(root)){path=session.DirectoryPath;File.WriteAllText(Path.Combine(path,"input.png"),"image");Directory.SetLastWriteTimeUtc(path,DateTime.UtcNow.AddDays(-10));Check(TransientSession.CleanupAbandoned(root)==0&&Directory.Exists(path),"Cleanup removed active session");}Check(!Directory.Exists(path),"Dispose left a session");using(var orphan=Spawn("--orphan",root)){Until(()=>File.Exists(Path.Combine(root,"ready")));path=File.ReadAllText(Path.Combine(root,"ready"));Check(TransientSession.CleanupAbandoned(root)==0,"Cleanup removed foreign active lease");orphan.Kill();orphan.WaitForExit();Check(TransientSession.CleanupAbandoned(root)==1&&!Directory.Exists(path),"Crash session was not cleaned");}
  string unknown;using(var session=TransientSession.Create(root)){unknown=session.DirectoryPath;File.WriteAllText(Path.Combine(unknown,"personal.txt"),"keep");}Check(Directory.Exists(unknown)&&TransientSession.CleanupAbandoned(root)==0,"Unknown files were removed");string foreign=Path.Combine(root,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(foreign);File.WriteAllText(Path.Combine(foreign,"input.png"),"keep");TransientSession.CleanupAbandoned(root);Check(Directory.Exists(foreign),"Unmarked directory was removed");
  string portable=Path.Combine(Home,"portable"),user=Path.Combine(Home,"per-user");Directory.CreateDirectory(portable);Directory.CreateDirectory(user);File.WriteAllText(Path.Combine(portable,"theme.txt"),"light");File.WriteAllText(Path.Combine(portable,"languages.json"),"{}");File.WriteAllText(Path.Combine(portable,"auth.json"),"never copy");File.WriteAllText(Path.Combine(portable,"ai-active-provider.txt"),"copilot");File.WriteAllText(Path.Combine(portable,"copilot-settings.json"),"{\"TranslationModel\":\"auto\"}");File.WriteAllText(Path.Combine(user,"theme.txt"),"dark");Check(AppStorage.ChooseSettingsDirectory(portable,user,p=>p==portable)==portable,"Writable portable changed");Check(AppStorage.ChooseSettingsDirectory(portable,user,p=>p==user)==user,"Readonly fallback failed");Check(File.ReadAllText(Path.Combine(user,"theme.txt"))=="dark"&&File.Exists(Path.Combine(user,"languages.json"))&&!File.Exists(Path.Combine(user,"auth.json"))&&File.ReadAllText(Path.Combine(user,"ai-active-provider.txt"))=="copilot"&&File.Exists(Path.Combine(user,"copilot-settings.json")),"Settings import unsafe or overwritten");Check(AppStorage.ChooseSettingsDirectory(portable,user,p=>false)==portable,"Unreadable fallback changed");
 }
 static System.Collections.Generic.IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var child in All(c))yield return child;}} // Native WM_PASTE does not retry OpenClipboard; Windows clipboard listeners can briefly hold it after SetText.
 static void PasteFixture(TextBox editor,string text){Clipboard.SetText(text);for(int attempt=0;attempt<20;attempt++){editor.SelectAll();editor.Paste();if(editor.Text==text)return;Application.DoEvents();Thread.Sleep(25);}}
 static void Editors(){bool rejected=false;try{Backend.Translate(new string('x',60000),"en",CancellationToken.None).GetAwaiter().GetResult();}catch(Exception e){rejected=e.Message.Contains("50,000");}Check(rejected,"Large translation did not fail before a CLI call");var flags=BindingFlags.NonPublic|BindingFlags.Instance;using(var form=new MainForm(true)){form.Show();Application.DoEvents();foreach(string name in new[]{"source","result"}){var editor=(TextBox)typeof(MainForm).GetField(name,flags).GetValue(form);Check(editor.MaxLength==TextPolicy.EditorMaximum,"Editor limit differs");if(name=="result")typeof(MainForm).GetMethod("CommitTranslationResult",flags).Invoke(form,new object[]{"Seed translation","source","en","English"});else editor.Text="";Check(!editor.ReadOnly,"Seeded editor locked before paste: "+name+" hasResult="+typeof(MainForm).GetField("hasTranslationResult",flags).GetValue(form));PasteFixture(editor,new string('A',60000));Check(editor.TextLength==60000,"Paste truncated: pane="+name+" length="+editor.TextLength+" clipboard="+Clipboard.GetText().Length+" readonly="+editor.ReadOnly);Check(!editor.ReadOnly,"Editor locked after initial paste: "+name+" hasResult="+typeof(MainForm).GetField("hasTranslationResult",flags).GetValue(form));editor.SelectAll();editor.Copy();Check(Clipboard.GetText().Length==60000,"Copy truncated: pane="+name+" clipboard="+Clipboard.GetText().Length+" selected="+editor.SelectionLength+" text="+editor.TextLength);bool expanded=false;using(var timer=new System.Windows.Forms.Timer{Interval=60}){timer.Tick+=(o,e)=>{var dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f.Visible&&f.Modal&&f.Owner==form&&f.Text.EndsWith(" — ScreenText"));if(dialog==null)return;var reader=All(dialog).OfType<TextBox>().First();if(!reader.Focused||!reader.Enabled)return;timer.Stop();Check(reader.MaxLength==editor.MaxLength,"Expanded limit differs");reader.SelectAll();int selected=reader.SelectionLength;PasteFixture(reader,new string('B',65000));Check(reader.TextLength==65000&&editor.Text==reader.Text,"Expanded large paste did not synchronize: pane="+name+" reader="+reader.TextLength+" original="+editor.TextLength+" clipboard="+Clipboard.GetText().Length+" readonly="+reader.ReadOnly+" selected="+selected+" max="+reader.MaxLength+" prefix="+reader.Text.Substring(0,Math.Min(5,reader.TextLength)));expanded=true;dialog.Close();};timer.Start();((Button)typeof(MainForm).GetField(name=="source"?"expandSourceButton":"expandResultButton",flags).GetValue(form)).PerformClick();}Check(expanded,"Expanded test did not run");}typeof(MainForm).GetMethod("ExitApplication",flags).Invoke(form,null);}}
 [STAThread]static int Main(string[] args){if(args[0].StartsWith("--"))return Probe(args[0],args[1]);try{Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Requests().GetAwaiter().GetResult();Storage();Application.EnableVisualStyles();var clipboard=Clipboard.GetDataObject();try{Editors();}finally{if(clipboard!=null)Clipboard.SetDataObject(clipboard,true);}File.WriteAllText(args[0],"PASS: cancellation, timeout, blocked stdin, parent exit, owner crash kill descendants; unrelated process survives. UTF8 output. Active leases preserved, orphan sessions reclaimed, unknown/unmarked content preserved. Readonly settings fallback/import without auth or overwrite. Main editors paste/copy 60,000 characters. No AI/auth/registry requests.");return 0;}catch(Exception e){File.WriteAllText(args[0],e.ToString());return 1;}}
